        node.setPrevious(null);
    }

    if (succ == null) {
        last = pred;
    } else {
        succ.setPrevious(pred);
        node.setNext(null);
    }

    node.item = null;
    size--;
    modCount++;
    return true;
}

private boolean unlink(ListNodeImpl<E> node){
    if (node == null) {
        return false;
    }
    ListNodeImpl<E> prev = node.getPrevious();
    ListNodeImpl<E> next = node.getNext();
    if (prev == null) {
        head = next;
    } else {
        prev.setNext(next);
        node.setPrevious(null);
    }
    if (next == null) {
        tail = prev;
    } else {
        next.setPrevious(prev);
        node.setNext(null);
    }
    node.setItem(null);
    size--;
    return true;
}

