private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    boolean escapeSeen = false;
    for (char c : input.toCharArray()) {
        if (escapeSeen) {
            switch (c) {
                case 'n':
                    sb.append('\n');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case '"':
                    sb.append('"');
                    break;
                default:
                    // Handle other escape characters if necessary
                    sb.append('\\').append(c);
                    break;
            }
            escapeSeen = false;
        } else if (c == '\\') {
            escapeSeen = true;
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

